//! Item logic for Did It Last.
//!
//! Pure functions over plain data: no storage, no I/O. The wasm bindings below are what the
//! Vue app calls; the same functions can be lifted into a server later. Values cross the
//! boundary as typed objects (`Ts<T>`), with TypeScript types generated by tsify.

pub mod changes;
pub mod item_changes;
pub mod items;

use chrono::NaiveDate;
use tsify::{Ts, Tsify};
use wasm_bindgen::prelude::*;

use changes::Stamp;
use item_changes::{ItemChange, ItemOp, Ledger};
use items::{Item, ItemProblem, ItemRow};

/// The core's crate version, so the app can show which build it is running.
#[wasm_bindgen(js_name = coreVersion)]
pub fn core_version() -> String {
    env!("CARGO_PKG_VERSION").to_string()
}

#[wasm_bindgen(js_name = itemRows)]
pub fn item_rows(items: Vec<Ts<Item>>, today: &str) -> Result<Vec<Ts<ItemRow>>, JsError> {
    items::item_rows(&to_rust(items)?, parse_date(today)?)
        .into_iter()
        .map(|row| Ok(row.into_ts()?))
        .collect()
}

#[wasm_bindgen(js_name = itemProblem)]
pub fn item_problem(item: Ts<Item>) -> Result<Option<Ts<ItemProblem>>, JsError> {
    Ok(items::item_problem(&item.to_rust()?)
        .map(|p| p.into_ts())
        .transpose()?)
}

fn parse_date(date: &str) -> Result<NaiveDate, JsError> {
    date.parse()
        .map_err(|_| JsError::new(&format!("not a YYYY-MM-DD date: {date}")))
}

/// The list, and the conflicts waiting for the user, from the whole change log.
#[wasm_bindgen]
pub fn ledger(changes: Vec<Ts<ItemChange>>) -> Result<Ts<Ledger>, JsError> {
    Ok(item_changes::ledger(&unwrap_changes(changes)?).into_ts()?)
}

/// The changes that record `edits` to one item, building on every change seen so far.
#[wasm_bindgen(js_name = recordItemEdits)]
pub fn record_item_edits(
    changes: Vec<Ts<ItemChange>>,
    #[wasm_bindgen(js_name = itemId)] item_id: &str,
    edits: Vec<Ts<ItemOp>>,
    stamp: Ts<Stamp>,
) -> Result<Vec<Ts<ItemChange>>, JsError> {
    let edits = to_rust(edits)?.into_iter().map(|op| op.0).collect();
    changes::record(&unwrap_changes(changes)?, item_id, edits, &stamp.to_rust()?)
        .into_iter()
        .map(|c| Ok(ItemChange(c).into_ts()?))
        .collect()
}

#[wasm_bindgen(js_name = itemEdits)]
pub fn item_edits(before: Option<Ts<Item>>, after: Ts<Item>) -> Result<Vec<Ts<ItemOp>>, JsError> {
    let before = before.map(|b| b.to_rust()).transpose()?;
    item_changes::item_edits(before.as_ref(), &after.to_rust()?)
        .into_iter()
        .map(|e| Ok(ItemOp(e).into_ts()?))
        .collect()
}

fn to_rust<T>(values: Vec<Ts<T>>) -> Result<Vec<T>, JsError>
where
    T: Tsify + serde::de::DeserializeOwned,
    T::JsType: Clone,
{
    Ok(values
        .into_iter()
        .map(|v| v.to_rust())
        .collect::<Result<Vec<_>, _>>()?)
}

fn unwrap_changes(
    changes: Vec<Ts<ItemChange>>,
) -> Result<Vec<changes::Change<item_changes::ItemEdit>>, JsError> {
    Ok(to_rust(changes)?.into_iter().map(|c| c.0).collect())
}
